    } else {
        // The lightest unmatched weight v can only pair with v + w: pick ordered partners, P(available, need).
        for (size_t i = 0; i < values.size(); i++) {
            long long need = counts[i];
            if (!need) continue;
            size_t j = lower_bound(values.begin(), values.end(), values[i] + w) - values.begin();
            long long available = j < values.size() && values[j] == values[i] + w ? counts[j] : 0;
