import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    private static final long MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long w = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (n % 2 == 1) {
            System.out.println(0);
            return;
        }
        Arrays.sort(a);
        long[] values = new long[n], counts = new long[n]; // distinct weights ascending, with their counts
        int size = 0;
        for (long v : a) {
            if (size == 0 || values[size - 1] != v) values[size++] = v;
            counts[size - 1]++;
        }
        long answer = 1;
        if (w == 0) {
            // Each weight group is matched within itself: (c - 1)!! ways.
            for (int i = 0; i < size; i++) {
                if (counts[i] % 2 == 1) {
                    System.out.println(0);
                    return;
                }
                for (long k = 1; k < counts[i]; k += 2) answer = answer * k % MOD;
            }
        } else {
            // The lightest unmatched weight v can only pair with v + w: pick ordered partners, P(available, need).
            for (int i = 0; i < size; i++) {
                long need = counts[i];
                if (need == 0) continue;
                int j = Arrays.binarySearch(values, 0, size, values[i] + w);
                long available = j >= 0 ? counts[j] : 0;
                if (available < need) {
                    System.out.println(0);
                    return;
                }
                for (long k = available - need + 1; k <= available; k++) answer = answer * k % MOD;
                counts[j] = available - need;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

const mod = 1000000007

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, w := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	if n%2 == 1 {
		os.Stdout.WriteString("0\n")
		return
	}
	slices.Sort(a)
	var values, counts []int // distinct weights ascending, with their counts
	for _, v := range a {
		if len(values) == 0 || values[len(values)-1] != v {
			values = append(values, v)
			counts = append(counts, 0)
		}
		counts[len(counts)-1]++
	}
	answer := 1
	if w == 0 {
		// Each weight group is matched within itself: (c - 1)!! ways.
		for _, c := range counts {
			if c%2 == 1 {
				os.Stdout.WriteString("0\n")
				return
			}
			for k := 1; k < c; k += 2 {
				answer = answer * k % mod
			}
		}
	} else {
		// The lightest unmatched weight v can only pair with v + w: pick ordered partners, P(available, need).
		for i, v := range values {
			need := counts[i]
			if need == 0 {
				continue
			}
			j, found := slices.BinarySearch(values, v+w)
			available := 0
			if found {
				available = counts[j]
			}
			if available < need {
				os.Stdout.WriteString("0\n")
				return
			}
			for k := available - need + 1; k <= available; k++ {
				answer = answer * k % mod
			}
			counts[j] = available - need
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
